      return false;
    }
    _organisms.set(instanceId, {
      ...descriptor,
      mountedAt: Date.now(),
      state: 'mounted',
    });
    permissions.grant(instanceId, perms || []);
    ledger._write({ type: 'organism_mounted', instanceId, id, label });
    bus.publish('kernel:organism-mounted', { instanceId, id, label, provides });
    return true;
